export const getSafeRel = (rel, target) => {
    if (target !== "_blank")
        return rel;
    const parts = rel ? rel.split(/\s+/) : [];
    if (!parts.includes("noopener"))
        parts.push("noopener");
    if (!parts.includes("noreferrer"))
        parts.push("noreferrer");
    return parts.join(" ");
};
