const RTL_ALIGNMENT_MAP = {
    top: "top",
    "top-left": "top-right",
    "top-right": "top-left",
    left: "right",
    "left-top": "right-top",
    "left-bottom": "right-bottom",
    right: "left",
    "right-top": "left-top",
    "right-bottom": "left-bottom",
    bottom: "bottom",
    "bottom-left": "bottom-right",
    "bottom-right": "bottom-left",
    // Logical values are already direction-aware; they don't flip in RTL
    "top-start": "top-start",
    "top-end": "top-end",
    start: "start",
    "start-top": "start-top",
    "start-bottom": "start-bottom",
    end: "end",
    "end-top": "end-top",
    "end-bottom": "end-bottom",
    "bottom-start": "bottom-start",
    "bottom-end": "bottom-end"
};
export const flipAlignment = (alignment) => RTL_ALIGNMENT_MAP[alignment];
