export const getToastAnimation = (isAdded, indx, removedId, toastLength, isMobile, activeFeedback) => {
    if (activeFeedback === "alert") {
        return null;
    }
    if (isMobile) {
        if (isAdded) {
            return "bottom-top";
        }
        if (removedId === 0) {
            return null;
        }
        return "top-bottom";
    }
    if (isAdded) {
        if (indx + 1 === toastLength) {
            return "right-left";
        }
        return "bottom-top";
    }
    const indxBeforeRemoved = indx + 1;
    if (removedId !== null && indxBeforeRemoved > removedId) {
        return null;
    }
    return "top-bottom";
};
